css:
/* Forest: a complete local theme. Native backdrop: mica. */
:root.theme-custom, body.theme-custom {
  --dc-surface-window: #edf3ed;
  --dc-surface-panel: #e1ebe1;
  --dc-surface-raised: #f9fcf7;
  --dc-surface-input: #f9fcf7;
  --dc-surface-hover: #d2e2d3;
  --dc-surface-active: #28633c;
  --dc-text-primary: #203b2a;
  --dc-text-secondary: #44604c;
  --dc-text-muted: #526b58;
  --dc-text-on-accent: #ffffff;
  --dc-border: #b1c8b5;
  --dc-border-strong: #73967b;
  --dc-accent: #28633c;
  --dc-accent-hover: #1e4f30;
  --dc-accent-soft: #cde4cf;
  --dc-success: #28633c;
  --dc-warning: #805500;
  --dc-danger: #b33038;
  --dc-info: #205e83;
  --dc-radius: 12px;
  --bg-body: var(--dc-surface-window);
  --bg-window: color-mix(in srgb, var(--dc-surface-window) calc(var(--surface-opacity) * 100%), transparent);
  --bg-content: var(--dc-surface-panel);
  --bg-toolbar: var(--dc-surface-panel);
  --bg-panel: var(--dc-surface-panel);
  --bg-element: var(--dc-surface-raised);
  --bg-input: var(--dc-surface-input);
  --text-primary: var(--dc-text-primary);
  --text-secondary: var(--dc-text-secondary);
  --text-muted: var(--dc-text-muted);
  --accent-color: var(--dc-accent);
  --accent-hover: var(--dc-accent-hover);
  --border-dark: var(--dc-border-strong);
  --border-light: var(--dc-border);
  --border-subtle: var(--dc-border);
  --radius-panel: 16px;
  --surface-dialog-bg: var(--dc-surface-raised);
  --surface-dialog-border: var(--dc-border);
  --surface-confirm-bg: var(--dc-surface-raised);
  --surface-confirm-border: var(--dc-border);
  --surface-settings-group-bg: var(--dc-surface-raised);
  --surface-settings-group-border: var(--dc-border);
  --control-confirm-btn-bg: var(--dc-surface-raised);
  --control-confirm-btn-text: var(--dc-text-primary);
  --control-confirm-btn-border: var(--dc-border);
  --control-segment-active-bg: var(--dc-accent);
  --control-segment-active-text: var(--dc-text-on-accent);
  --icon-btn-bg: var(--dc-surface-raised);
  --icon-btn-color: var(--dc-text-primary);
  --icon-btn-border: 1px solid var(--dc-border);
  --icon-btn-radius: 9px;
  --icon-btn-hover-bg: var(--dc-surface-hover);
  --icon-btn-hover-border: var(--dc-border-strong);
  --icon-btn-active-bg: var(--dc-accent);
  --icon-btn-active-border: var(--dc-accent);
  --icon-btn-active-color: var(--dc-text-on-accent);
}
:root.theme-custom.dark-mode, body.theme-custom.dark-mode {
  --dc-surface-window: #17251c;
  --dc-surface-panel: #203127;
  --dc-surface-raised: #293d30;
  --dc-surface-input: #203127;
  --dc-surface-hover: #334e3b;
  --dc-surface-active: #9acba4;
  --dc-text-primary: #edf6eb;
  --dc-text-secondary: #c2d6c3;
  --dc-text-muted: #a6bda8;
  --dc-text-on-accent: #17251c;
  --dc-border: #49634f;
  --dc-border-strong: #72957b;
  --dc-accent: #9acba4;
  --dc-accent-hover: #b0dfb8;
  --dc-accent-soft: #2c4c36;
  --dc-success: #94d6a1;
  --dc-warning: #e2c478;
  --dc-danger: #ffa4a9;
  --dc-info: #96cceb;
}
body.theme-custom #root {
  border: 1px solid var(--dc-border-strong);
  border-radius: 18px;
  background: var(--bg-window);
  box-shadow: 0 14px 42px #0b24152b;
}
.theme-custom header {
  padding: 12px 0;
  border-bottom: 1px solid var(--dc-border);
  background: linear-gradient(110deg, var(--dc-surface-raised), var(--dc-surface-panel));
}
.theme-custom .header-title {
  padding: 2px 0;
  color: var(--dc-text-primary);
  background: transparent;
  text-transform: none;
  font-size: 17px;
  font-weight: 650;
  letter-spacing: 0.4px;
}
.theme-custom .search-input {
  border: 1px solid var(--dc-border);
  border-radius: 12px 12px 4px 12px;
  box-shadow: none;
  font-weight: 400;
}
.theme-custom .history-item {
  margin: 7px 10px;
  border: 1px solid var(--dc-border);
  border-inline-start: 3px solid var(--dc-border-strong);
  border-radius: 4px 12px 12px 4px;
  background: var(--dc-surface-raised);
  box-shadow: 0 2px 6px #0b241510;
}
.theme-custom .history-item:hover { background: var(--dc-surface-hover); }
.theme-custom .history-item.selected { border-color: var(--dc-accent); background: var(--dc-accent-soft); }
.theme-custom :is(.settings-group, .data-panel, .data-info-box) {
  border: 1px solid var(--dc-border);
  border-radius: 14px;
  background: var(--dc-surface-raised);
  box-shadow: 0 3px 12px #0b241510;
}
.theme-custom :is(.group-header, .settings-sidebar, .queue-bar) {
  background: var(--dc-surface-panel);
  border-color: var(--dc-border);
}
.theme-custom :is(.setting-input, .modal-textarea, .modal-input, .react-select__control) {
  border: 1px solid var(--dc-border);
  border-radius: 9px;
  color: var(--dc-text-primary);
  background: var(--dc-surface-input);
  box-shadow: none;
}
.theme-custom :is(.confirm-dialog, .modal-content, .item-context-menu, .compact-popover) {
  border: 1px solid var(--dc-border-strong);
  border-radius: 16px;
  color: var(--dc-text-primary);
  background: var(--dc-surface-raised);
  box-shadow: 0 12px 38px #0b241530;
}
.theme-custom .settings-rail-item { border-radius: 4px 12px 12px 4px; }
.theme-custom :is(button, input, select, textarea):focus-visible { outline: 2px solid var(--dc-accent); outline-offset: 2px; }
.theme-custom .confirm-dialog-btn-primary { background: var(--dc-accent); color: var(--dc-text-on-accent); border-color: var(--dc-accent); }
.theme-custom .confirm-dialog-btn-primary:hover { background: var(--dc-accent-hover); }
@media (prefers-reduced-motion: reduce) {
  .theme-custom :is(button, .history-item) { transition: none; }
}
